import "@/global.css";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Stack } from "expo-router";
import Head from "expo-router/head";
import { StatusBar } from "expo-status-bar";
import { useCallback, useEffect, useMemo, useState } from "react";
import { GestureHandlerRootView } from "react-native-gesture-handler";
import "react-native-reanimated";
import { Platform } from "react-native";
import { useFonts } from "expo-font";
import "@/lib/_core/nativewind-pressable";
import { ThemeProvider } from "@/lib/theme-provider";
import {
  SafeAreaFrameContext,
  SafeAreaInsetsContext,
  SafeAreaProvider,
  initialWindowMetrics,
} from "react-native-safe-area-context";
import type { EdgeInsets, Metrics, Rect } from "react-native-safe-area-context";

import { trpc, createTRPCClient } from "@/lib/trpc";
import { initManusRuntime, subscribeSafeAreaInsets } from "@/lib/_core/manus-runtime";
import { FavoritesProvider } from "@/lib/favorites-store";
import { initNotificationHandler, setupAndroidChannel, registerPushTokenWithServer } from "@/lib/notifications";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useRouter, useSegments } from "expo-router";
import { WebPushPrompt } from "@/components/web-push-prompt";
import { UpdatePrompt } from "@/components/update-prompt";

const DEFAULT_WEB_INSETS: EdgeInsets = { top: 0, right: 0, bottom: 0, left: 0 };
const DEFAULT_WEB_FRAME: Rect = { x: 0, y: 0, width: 0, height: 0 };

export const unstable_settings = {
  anchor: "(tabs)",
};

export default function RootLayout() {
  const [fontsLoaded] = useFonts({
    'DancingScript': require('@/assets/fonts/DancingScript-Regular.ttf'),
    'DancingScript-Bold': require('@/assets/fonts/DancingScript-Bold.ttf'),
  });

  const initialInsets = initialWindowMetrics?.insets ?? DEFAULT_WEB_INSETS;
  const initialFrame = initialWindowMetrics?.frame ?? DEFAULT_WEB_FRAME;

  const [insets, setInsets] = useState<EdgeInsets>(initialInsets);
  const [frame, setFrame] = useState<Rect>(initialFrame);

  // Initialize Manus runtime for cookie injection from parent container
  useEffect(() => {
    initManusRuntime();
  }, []);

  const [onboardingDone, setOnboardingDone] = useState<boolean | null>(null);

  // Check onboarding status
  useEffect(() => {
    AsyncStorage.getItem("seelenplanerin_onboarding_done").then((val) => {
      setOnboardingDone(val === "true");
    }).catch(() => setOnboardingDone(true)); // fallback: skip onboarding on error
  }, []);

  // Initialize notification handler + Push-Token registrieren
  useEffect(() => {
    initNotificationHandler();
    setupAndroidChannel();
    // Push-Token beim Server registrieren (nach kurzem Delay für App-Init)
    const timer = setTimeout(() => {
      registerPushTokenWithServer().catch(() => {});
    }, 3000);
    return () => clearTimeout(timer);
  }, []);

  const handleSafeAreaUpdate = useCallback((metrics: Metrics) => {
    setInsets(metrics.insets);
    setFrame(metrics.frame);
  }, []);

  useEffect(() => {
    if (Platform.OS !== "web") return;
    const unsubscribe = subscribeSafeAreaInsets(handleSafeAreaUpdate);
    return () => unsubscribe();
  }, [handleSafeAreaUpdate]);

  // Create clients once and reuse them
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            // Disable automatic refetching on window focus for mobile
            refetchOnWindowFocus: false,
            // Retry failed requests once
            retry: 1,
          },
        },
      }),
  );
  const [trpcClient] = useState(() => createTRPCClient());

  // Ensure minimum 8px padding for top and bottom on mobile
  const providerInitialMetrics = useMemo(() => {
    const metrics = initialWindowMetrics ?? { insets: initialInsets, frame: initialFrame };
    return {
      ...metrics,
      insets: {
        ...metrics.insets,
        top: Math.max(metrics.insets.top, 16),
        bottom: Math.max(metrics.insets.bottom, 12),
      },
    };
  }, [initialInsets, initialFrame]);

  const content = (
    <GestureHandlerRootView style={{ flex: 1 }}>
      {Platform.OS === "web" && (
        <Head>
          <link rel="apple-touch-icon" href="/apple-touch-icon.png" />
          <link rel="manifest" href="/manifest.json" />
          <meta name="apple-mobile-web-app-capable" content="yes" />
          <meta name="apple-mobile-web-app-status-bar-style" content="default" />
          <meta name="apple-mobile-web-app-title" content="Seelenplanerin" />
          <meta name="theme-color" content="#C9A96E" />
        </Head>
      )}
      <trpc.Provider client={trpcClient} queryClient={queryClient}>
        <QueryClientProvider client={queryClient}>
          <FavoritesProvider>
          {/* Default to hiding native headers so raw route segments don't appear (e.g. "(tabs)", "products/[id]"). */}
          {/* If a screen needs the native header, explicitly enable it and set a human title via Stack.Screen options. */}
          {/* in order for ios apps tab switching to work properly, use presentation: "fullScreenModal" for login page, whenever you decide to use presentation: "modal*/}
          <Stack screenOptions={{ headerShown: false }}
            initialRouteName={onboardingDone === false ? "onboarding" : "(tabs)"}
          >
            <Stack.Screen name="onboarding" options={{ gestureEnabled: false }} />
            <Stack.Screen name="(tabs)" />
            <Stack.Screen name="oauth/callback" />
            <Stack.Screen name="content/[id]" options={{ presentation: "card" }} />
            <Stack.Screen name="aura" options={{ presentation: "card" }} />
            <Stack.Screen name="seelenimpuls" options={{ presentation: "card" }} />
            <Stack.Screen name="mondtyp-quiz" options={{ presentation: "card" }} />
            <Stack.Screen name="runen-quiz" options={{ presentation: "card" }} />
            <Stack.Screen name="shop/index" options={{ presentation: "card" }} />
            <Stack.Screen name="buchen/index" options={{ presentation: "card" }} />
            <Stack.Screen name="runen/set/[id]" options={{ presentation: "card" }} />
            <Stack.Screen name="runen-screen" options={{ presentation: "card" }} />
            <Stack.Screen name="admin" options={{ presentation: "card" }} />
            <Stack.Screen name="journal/write" options={{ presentation: "card" }} />
            <Stack.Screen name="kerzen-quiz" options={{ presentation: "card" }} />
            <Stack.Screen name="musik" options={{ presentation: "card" }} />
            <Stack.Screen name="benachrichtigungen" options={{ presentation: "card" }} />
            <Stack.Screen name="nachrichten" options={{ presentation: "card" }} />
            <Stack.Screen name="rituale/[slug]" options={{ presentation: "card" }} />
            <Stack.Screen name="impressum" options={{ presentation: "card" }} />
          </Stack>
          <StatusBar style="auto" />
          <WebPushPrompt />
          <UpdatePrompt />
          </FavoritesProvider>
        </QueryClientProvider>
      </trpc.Provider>
    </GestureHandlerRootView>
  );

  const shouldOverrideSafeArea = Platform.OS === "web";

  if (shouldOverrideSafeArea) {
    return (
      <ThemeProvider>
        <SafeAreaProvider initialMetrics={providerInitialMetrics}>
          <SafeAreaFrameContext.Provider value={frame}>
            <SafeAreaInsetsContext.Provider value={insets}>
              {content}
            </SafeAreaInsetsContext.Provider>
          </SafeAreaFrameContext.Provider>
        </SafeAreaProvider>
      </ThemeProvider>
    );
  }

  return (
    <ThemeProvider>
      <SafeAreaProvider initialMetrics={providerInitialMetrics}>{content}</SafeAreaProvider>
    </ThemeProvider>
  );
}
